#!/usr/bin/env python3
"""Actual SDK project-extension wildcard additions must stale compiled domains."""
import argparse,hashlib,importlib.util,json,shutil,subprocess,tempfile
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
def main():
 p=argparse.ArgumentParser();p.add_argument('binary',type=Path);p.add_argument('--helper',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args()
 s=importlib.util.spec_from_file_location('prep',ROOT/'docs/review/prepared-replay.py');prep=importlib.util.module_from_spec(s);s.loader.exec_module(prep);n=prep.load('native',ROOT/'docs/review/native-smoke-replay.py');base=Path(tempfile.mkdtemp(prefix='sdk-import-membership-',dir=ROOT/'.tmp'));binary=base/'fsharp-navigator';shutil.copy2(a.binary,binary)
 root=n.fixture(base,'consumer',{'A.fs':'module A\nlet value = 1\n','B.fs':'module B\nlet answer = A.value\n'});project=root/'Test.fsproj';project.write_text(project.read_text().replace('<Compile Include="B.fs"/>',''))
 report={'binarySha256':hashlib.sha256(binary.read_bytes()).hexdigest(),'helperSha256':hashlib.sha256(a.helper.read_bytes()).hexdigest(),'fixtureRoot':str(base),'projectXml':project.read_text(),'sources':{'A.fs':(root/'A.fs').read_text(),'B.fs':(root/'B.fs').read_text()},'builds':[prep.build(project)],'sessions':[],'provenance':'Real SDK project extension import, unchanged existing project/source/environment inputs; adding obj/Test.fsproj.extra.targets introduces an already-existing B.fs after A.fs.'}
 def evaluate(label):
  r=subprocess.run([str(prep.DOTNET),str(a.helper.resolve()),'--once'],input=json.dumps({'id':1,'method':'workspace/evaluate','params':{'root':str(root)}})+'\n',env=prep.ENV,text=True,capture_output=True,timeout=120);v=json.loads(r.stdout);assert 'error' not in v,v;model=v['result'];path=base/(label+'.json');path.write_text(json.dumps(model));return model,path
 def query(model):
  requests=[{'id':1,'method':'workspace/open','params':{'root':str(root),'mode':'indexed','cacheDir':str(base/'cache'),'evaluatedModelPath':str(model)}},{'id':2,'method':'navigation/references','params':{'path':str(root/'A.fs'),'line':1,'character':4,'includeDeclaration':False}},{'id':3,'method':'shutdown','params':{}}]
  r=subprocess.run([str(binary),'daemon'],input=''.join(json.dumps(x)+'\n' for x in requests),env=prep.ENV,text=True,capture_output=True,timeout=30);responses=[json.loads(x) for x in r.stdout.splitlines()];report['sessions'].append({'requests':requests,'responses':responses,'stderr':r.stderr});return next(x for x in responses if x.get('id')==2)
 old,oldpath=evaluate('before-model');report['initialModel']={'path':str(oldpath),'projects':[{'files':p['files'],'membershipReusable':p['membershipReusable'],'membershipDiagnostics':p['membershipDiagnostics'],'sourceMembership':p['sourceMembership'],'environmentInputCount':len(p.get('environmentCertificate',{}).get('inputs',[]))} for p in old['projects']]};report['before']=query(oldpath)
 added=root/'obj/Test.fsproj.extra.targets';added.write_text('<Project><ItemGroup><Compile Include="B.fs"/></ItemGroup></Project>');report['addedImport']={'path':str(added),'text':added.read_text()}
 r=subprocess.run([str(prep.DOTNET),'build',str(project),'--no-restore','--nologo','-v:q','-m:1','-nodeReuse:false'],env=prep.ENV,text=True,capture_output=True,timeout=90);assert r.returncode==0,r.stdout+r.stderr;report['builds'].append({'exitCode':r.returncode,'stdout':r.stdout,'stderr':r.stderr})
 report['changedCertifiedFiles']=[x['path'] for x in old['inputHashes'] if (hashlib.sha256(Path(x['path']).read_bytes()).hexdigest() if Path(x['path']).is_file() else 'directory' if Path(x['path']).is_dir() else 'missing')!=x['sha256']]
 report['afterOldModel']=query(oldpath);fresh,freshpath=evaluate('after-model');report['freshFiles']=[p['files'] for p in fresh['projects']];report['afterFreshModel']=query(freshpath)
 expected=[n.location(root/'B.fs',1,15,5)];v=report['afterOldModel'].get('result',{});report['expectedLocations']=expected;report['status']='wrong-exact' if v.get('completeness')=='exact' and n.normalized(v.get('locations',[]))!=n.normalized(expected) else ('pass' if v.get('completeness')=='exact' else 'safe-rejection');a.output.write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'status':report['status'],'initialModel':report['initialModel'],'changedCertifiedFiles':report['changedCertifiedFiles'],'before':report['before'],'afterOldModel':report['afterOldModel'],'afterFreshModel':report['afterFreshModel']},indent=2))
if __name__=='__main__':main()
